-- 028: trusted agricultural knowledge retrieval and assistant request controls
create table if not exists public.agri_knowledge_sources (id uuid primary key default gen_random_uuid(), title text not null, publisher text not null, source_url text not null unique, source_type text not null default 'guideline' check (source_type in ('guideline','research','extension','government')), published_on date, locality_tags text[] not null default '{}', crop_tags text[] not null default '{}', language text not null default 'en', status text not null default 'pending' check (status in ('pending','approved','archived')), created_at timestamptz not null default now(), reviewed_at timestamptz);
create table if not exists public.agri_knowledge_chunks (id uuid primary key default gen_random_uuid(), source_id uuid not null references public.agri_knowledge_sources(id) on delete cascade, chunk_index integer not null check (chunk_index >= 0), heading text, content text not null check (char_length(content) between 40 and 12000), locality_tags text[] not null default '{}', crop_tags text[] not null default '{}', search_document tsvector generated always as (to_tsvector('simple', coalesce(heading,'') || ' ' || content)) stored, created_at timestamptz not null default now(), unique(source_id,chunk_index));
create index if not exists agri_knowledge_chunks_search_idx on public.agri_knowledge_chunks using gin(search_document);
create index if not exists agri_knowledge_chunks_locality_idx on public.agri_knowledge_chunks using gin(locality_tags);
create index if not exists agri_knowledge_chunks_crop_idx on public.agri_knowledge_chunks using gin(crop_tags);
alter table public.agri_knowledge_sources enable row level security;
alter table public.agri_knowledge_chunks enable row level security;
revoke all on public.agri_knowledge_sources, public.agri_knowledge_chunks from anon,authenticated;
grant select on public.agri_knowledge_sources, public.agri_knowledge_chunks to authenticated;
create policy "Approved agricultural sources are readable" on public.agri_knowledge_sources for select to authenticated using (status='approved');
create policy "Approved agricultural chunks are readable" on public.agri_knowledge_chunks for select to authenticated using (exists(select 1 from public.agri_knowledge_sources s where s.id=source_id and s.status='approved'));
create or replace function public.search_agri_knowledge(query_text text,locality_filter text default null,crop_filter text default null,result_limit integer default 5) returns table(chunk_id uuid,source_id uuid,title text,publisher text,source_url text,published_on date,heading text,content text,locality_tags text[],crop_tags text[],rank real) language sql stable security invoker set search_path='' as $$ select c.id,s.id,s.title,s.publisher,s.source_url,s.published_on,c.heading,c.content,c.locality_tags,c.crop_tags,ts_rank_cd(c.search_document,websearch_to_tsquery('simple',coalesce(query_text,'')))::real from public.agri_knowledge_chunks c join public.agri_knowledge_sources s on s.id=c.source_id where s.status='approved' and char_length(trim(coalesce(query_text,'')))>=2 and c.search_document @@ websearch_to_tsquery('simple',query_text) and (locality_filter is null or c.locality_tags && array[locality_filter,'Vhembe','Limpopo']::text[] or s.locality_tags && array[locality_filter,'Vhembe','Limpopo']::text[]) and (crop_filter is null or c.crop_tags && array[crop_filter]::text[] or s.crop_tags && array[crop_filter]::text[]) order by ts_rank_cd(c.search_document,websearch_to_tsquery('simple',coalesce(query_text,''))) desc,s.published_on desc nulls last limit greatest(1,least(coalesce(result_limit,5),8)); $$;
revoke all on function public.search_agri_knowledge(text,text,text,integer) from public,anon;
grant execute on function public.search_agri_knowledge(text,text,text,integer) to authenticated;
create table if not exists private.assistant_rate_limits(user_id uuid not null references auth.users(id) on delete cascade,window_start timestamptz not null,request_count integer not null default 0,primary key(user_id,window_start));
revoke all on private.assistant_rate_limits from public,anon,authenticated;
create or replace function private.consume_assistant_rate_limit() returns boolean language plpgsql security definer set search_path='' as $$ declare v_user uuid:=auth.uid(); v_window timestamptz:=date_trunc('minute',now()); v_count integer; begin if v_user is null then return false; end if; insert into private.assistant_rate_limits(user_id,window_start,request_count) values(v_user,v_window,1) on conflict(user_id,window_start) do update set request_count=private.assistant_rate_limits.request_count+1 returning request_count into v_count; return v_count<=12; end; $$;
revoke all on function private.consume_assistant_rate_limit() from public,anon;
grant execute on function private.consume_assistant_rate_limit() to authenticated;